"""Workspace tool and tool-settings UI."""

import os
import sys

import bpy
from bpy.types import Operator, Panel, WorkSpaceTool

from .. import cutting
from ..lib.constants import TOOL_IDNAME, logger
from .gizmos import CutPlaneGroup

# Custom toolbar icon (geometry .dat, generated by tools/make_tool_icon.py).
# The tool system joins the icon name with the system icons dir - an ABSOLUTE
# path survives that join unchanged (the official addon-template approach),
# and ".dat" is appended by the loader.
# icons/ lives at the package ROOT (one level above this ui/ module).
_ICON_HANDLE = os.path.join(os.path.dirname(os.path.dirname(__file__)),
                            "icons", "mesh_tool.cut_plane")


class CUT_PLANE_PT_snapping(Panel):
    """Snapping options."""
    # Tool-LOCAL snap (cut_plane.snap_*), independent of Blender's global
    # snap. Modes that can't apply to a single virtual point are omitted: Snap
    # Base (the base is always the plane center), Volume, Edge Perpendicular,
    # the individual-element projection modes, and Target Selection.
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'HEADER'
    bl_label = "Cut Plane Snapping"

    def draw(self, context):
        layout = self.layout
        props = getattr(context.window_manager, 'cut_plane', None)
        if props is None:
            return

        col = layout.column()
        col.label(text="Snap Target")
        # ONE expanded enum-flag prop - the exact widget native's snapping
        # popover uses (space_view3d.py VIEW3D_PT_snapping: col.prop(...,
        # "snap_elements_base", expand=True)). This is both the LOOK
        # (left-aligned icon rows) and the SEMANTICS: plain click selects
        # exclusively, Shift/Ctrl+click toggles into a multi-selection.
        # The per-item rows this replaces toggled each target independently
        # (centered buttons, no Shift behavior) - nothing like native.
        col.prop(props, "snap_elements", expand=True)

        col.separator()
        col.prop(props, "snap_align_rotation")

        col.separator()
        col.label(text="Affect")
        row = col.row(align=True)
        row.prop(props, "snap_affect_move", text="Move", toggle=True)
        row.prop(props, "snap_affect_rotate", text="Rotate", toggle=True)
        row.prop(props, "snap_affect_scale", text="Scale", toggle=True)

        col.separator()
        col.label(text="Rotation Increment")
        row = col.row(align=True)
        row.prop(props, "snap_angle_increment", text="")
        row.prop(props, "snap_angle_increment_precision", text="")


class CUT_PLANE_PT_cut_options(Panel):
    """Extra cut options."""
    # Native overflow pattern: the tool header keeps the primary options inline
    # and puts the rest behind a "..." popover (like TOPBAR_PT_tool_settings_extra).
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'HEADER'
    bl_label = "Cut Options"

    def draw(self, context):
        layout = self.layout
        props = getattr(context.window_manager, 'cut_plane', None)
        if props is None:
            return
        col = layout.column()
        col.label(text="Selection")
        # Selected Only makes selection the cut's INPUT domain, so the
        # loop-select OUTPUT options are off the table while it is on.
        col.active = not props.cut_selected_only
        col.prop(props, "cut_select_loop")


class CutPlaneTool(WorkSpaceTool):
    """
    Workspace tool that activates the cut plane in Edit Mode.

    Appears in Edit Mode toolbar. When selected, shows gizmo at mesh origin.
    """
    bl_space_type = 'VIEW_3D'
    bl_context_mode = 'EDIT_MESH'
    bl_idname = TOOL_IDNAME
    bl_label = "Cut Plane"
    bl_description = (
        "Slice the mesh with a positionable plane, previewing the cut live.\n"
        "Move, rotate or scale the plane, then press Enter to cut"
    )
    # WorkSpaceTool icons are toolbar icon datafiles (.dat geometry), not icon
    # enum names. Ours: a native-gray cube sliced by the tool's orange plane
    # (shipped in icons/, regenerate with tools/make_tool_icon.py).
    bl_icon = _ICON_HANDLE
    bl_widget = CutPlaneGroup.bl_idname
    # Tool-scoped shortcuts: while this tool is active, G / R / S transform THE
    # PLANE directly, native-style - the plane is the manipulation subject here,
    # so the transform keys act on it exactly like they act on geometry outside
    # the tool. G grabs (plane follows the mouse immediately), R rotates around
    # the view axis (what bare native R does), S scales uniformly from the plane
    # center. Click/Enter confirms, Esc cancels, typed numbers work, snapping and
    # Shift-precision behave as in the gizmo drags (same modal operators - they
    # read the start mouse position from the invoking event, so a key press works
    # like a handle click). Mid-modal G/R/S switches transforms WITHOUT
    # confirming, native-style (start pose restored, then the other transform
    # begins - modal_base step 2b), and the active X/Y/Z constraint carries
    # over (G-X then R rotates around X, also native); R-R toggles
    # view-rotate <-> trackball. Native G/R/S return on tool switch. Gizmo
    # MODE switching lives in the tool header (the transforms are transient
    # and do not flip the visible gizmo set, like native).
    #
    # Enter = Execute Cut (both Enter keys, like native confirm). Safe to bind:
    # outside modals Enter is unbound in the edit-mode 3D view, and DURING a
    # transform the BLOCKING modal consumes Enter as its confirm - the tool
    # keymap only sees the key when nothing is running (it fires on PRESS, so
    # the release after a modal confirm doesn't trigger a cut). The keymap
    # invocation runs the operator's invoke(), the exact path the Cut button
    # takes (snapshot plane + options, then execute).
    # Alt+G / Alt+R / Alt+S = clear the plane's location / rotation / scale -
    # the native clear-transform vocabulary applied to the plane (Alt+G
    # returns it to the mesh center). One operator, per-channel via the
    # keymap-set mode property; the header Reset button clears everything.
    #
    # The frozen template, defined below (_TOOL_KEYMAP) and assigned right
    # after it. NEVER rebuilt at runtime: the user's own edits live in the
    # keymap Blender builds from this, and are read back from there.
    bl_keymap = ()

    @staticmethod
    def draw_settings(context, layout, tool):
        """Tool options - drawn in the header tool-settings row and
        automatically mirrored into the Active Tool panel (N-panel Tool
        tab and the Properties editor).

        Native convention (space_toolsystem_toolbar.py): the TOOL_HEADER
        gets a compact inline row - segmented enums, labeled dropdowns,
        plain checkboxes (knife/inset style), a "..." popover for options
        that don't fit - while every other region gets the property-split
        vertical layout with heading groups (the Active Tool panel look).
        """
        props = getattr(context.window_manager, 'cut_plane', None)
        if props is None:
            return
        if context.region.type == 'TOOL_HEADER':
            CutPlaneTool._draw_settings_header(context, layout, props)
        else:
            CutPlaneTool._draw_settings_panel(context, layout, props)

    @staticmethod
    def _edge_case_warning(context, props):
        """The warning for states where the tool silently does nothing, or
        None: an empty Selected-Only domain (the preview cuts nothing until
        something is selected), and the live-preview blockers on the ACTIVE
        mesh (shape keys / density cap - cutting.live_preview_blocker, the
        engine's own guard, so the UI can never claim a preview the engine
        refuses; blocked non-active meshes warn in the console). Drawn with
        the yellow warning triangle (no alert tint - a caution, not an
        error) in the tool header and the Active Tool panel."""
        obj = context.edit_object
        if obj is None or obj.type != 'MESH':
            return None
        # Everything the cut targets (multi-object edit; active-only fallback
        # for restricted contexts)
        objects = [ob for ob in getattr(context, 'objects_in_mode_unique_data', ())
                   if ob.type == 'MESH'] or [obj]

        def selected_verts(ob):
            # The cut's domain is the BASELINE selection (Execute restores
            # it before bisecting, folding any pending selection change in
            # first) - so the warning reads what the engine WILL see: the
            # LIVE selection while a change is pending, the baseline
            # otherwise. Reading only the live mesh made the header say
            # "Nothing selected to cut" about a cut that would succeed -
            # with a Clear on, the preview DELETES the selected side and
            # total_vert_sel reads 0 while the baseline holds the domain.
            counts = cutting.baseline_selection_counts(ob)
            if counts is None or cutting.selection_change_pending(ob):
                return ob.data.total_vert_sel
            return counts[0]

        if props.cut_selected_only and all(
                selected_verts(ob) == 0 for ob in objects):
            return "Nothing selected to cut"
        try:
            # A running preview proves there is no blocker - skip the bmesh
            # peek on that common path (this runs on every header redraw)
            if cutting.get_live_snapshot_mesh(obj) is not None:
                blocker = None
            else:
                blocker = cutting.live_preview_blocker(obj)
        except Exception:
            return None  # a draw function must never raise over a warning
        if blocker is not None:
            return f"No live preview: {blocker}"
        return None

    @staticmethod
    def _draw_snap_pair(layout, props):
        """The tool's OWN magnet toggle + target popover pair, independent of
        Blender's global snap. Icon/label logic mirrors the native header
        (space_view3d.py), driven by the tool's snap_elements (identifiers
        and icons match native)."""
        snap_items = props.bl_rna.properties["snap_elements"].enum_items
        snap_elements = props.snap_elements
        if len(snap_elements) == 1:
            text = ""
            icon = 'NONE'
            for elem in snap_elements:
                icon = snap_items[elem].icon
                break
        else:
            text = "Mix"
            icon = 'NONE'

        row = layout.row(align=True)
        row.prop(props, "snap_use", text="", icon='SNAP_ON', toggle=True)
        sub = row.row(align=True)
        sub.popover(panel="CUT_PLANE_PT_snapping", icon=icon, text=text)

    @staticmethod
    def _draw_settings_header(context, layout, props):
        """Compact header row: plane group | cut group, native ordering
        (options first, the action button last)."""
        # --- the plane: what/where -------------------------------------
        # Gizmo pair: the handle toggle + WHICH handle set, as one aligned
        # unit. The mode is purely a gizmo concern (keyboard G/R/S work in
        # any mode), so instead of three prime-space segment buttons it
        # rides next to the toggle as a compact icon dropdown and greys out
        # while the handles are hidden.
        row = layout.row(align=True)
        row.prop(props, "show_gizmo_handles", text="", icon='GIZMO', toggle=True)
        sub = row.row(align=True)
        sub.active = props.show_gizmo_handles
        sub.prop(props, "mode", text="")
        # Orientation exactly like the native header dropdown: item icon +
        # name, no "Orientation:" label prefix.
        layout.prop(props, "orientation", text="")
        CutPlaneTool._draw_snap_pair(layout, props)
        layout.operator("view3d.cut_plane_reset", text="Reset", icon='LOOP_BACK')

        # --- the cut: options, extras, action ---------------------------
        # Fill / Clear Inner / Clear Outer drive both the live preview and
        # what Execute commits (the Cut button snapshots them into the
        # operator for the F9 redo panel). Checkboxes, not toggle buttons -
        # the native edit-tool header style (knife, inset), and the exact
        # names native Bisect uses.
        layout.separator()
        layout.prop(props, "cut_use_fill")
        layout.prop(props, "cut_clear_inner")
        layout.prop(props, "cut_clear_outer")
        # Mirror toggles, sculpt-symmetry style: icon + compact X Y Z row,
        # plus the ghost-visibility eye (display only; greyed while no
        # mirror is on - there is nothing to show or hide then)
        row = layout.row(align=True)
        row.label(text="", icon='MOD_MIRROR')
        row.prop(props, "mirror_x", text="X", toggle=True)
        row.prop(props, "mirror_y", text="Y", toggle=True)
        row.prop(props, "mirror_z", text="Z", toggle=True)
        sub = row.row(align=True)
        sub.active = props.mirror_x or props.mirror_y or props.mirror_z
        sub.prop(props, "show_mirror_planes", text="",
                 icon='HIDE_OFF' if props.show_mirror_planes else 'HIDE_ON')
        layout.prop(props, "cut_selected_only")
        layout.popover(panel="CUT_PLANE_PT_cut_options", text="...")
        warning = CutPlaneTool._edge_case_warning(context, props)
        if warning:
            layout.label(text=warning, icon='ERROR')
        layout.operator("view3d.cut_plane_cut", text="Cut", icon='MOD_BOOLEAN')

    @staticmethod
    def _draw_settings_panel(context, layout, props):
        """Active Tool panel: property-split column with heading groups,
        the native panel rendering of tool settings."""
        layout.use_property_split = True
        layout.use_property_decorate = False

        layout.prop(props, "show_gizmo_handles")
        row = layout.row()
        row.active = props.show_gizmo_handles  # handle set - moot when hidden
        row.prop(props, "mode", expand=True)
        layout.prop(props, "orientation")

        col = layout.column(heading="Snap")
        row = col.row(align=True)
        row.prop(props, "snap_use", text="")
        row.popover(panel="CUT_PLANE_PT_snapping", text="Targets")

        col = layout.column(heading="Cut")
        col.prop(props, "cut_use_fill")
        col.prop(props, "cut_clear_inner")
        col.prop(props, "cut_clear_outer")
        col.prop(props, "cut_selected_only")

        # Native sculpt-symmetry panel look: one aligned X/Y/Z toggle row
        col = layout.column(heading="Mirror", align=True)
        row = col.row(align=True)
        row.prop(props, "mirror_x", text="X", toggle=True)
        row.prop(props, "mirror_y", text="Y", toggle=True)
        row.prop(props, "mirror_z", text="Z", toggle=True)
        sub = col.row()
        sub.active = props.mirror_x or props.mirror_y or props.mirror_z
        sub.prop(props, "show_mirror_planes")

        col = layout.column(heading="Selection")
        col.active = not props.cut_selected_only  # selection = input domain then
        col.prop(props, "cut_select_loop")

        warning = CutPlaneTool._edge_case_warning(context, props)
        if warning:
            layout.label(text=warning, icon='ERROR')

        layout.separator()
        row = layout.row(align=True)
        row.operator("view3d.cut_plane_reset", text="Reset", icon='LOOP_BACK')
        row.operator("view3d.cut_plane_cut", text="Cut", icon='MOD_BOOLEAN')


# Exact name register_tool gives our keymap ("<space UI name> Tool:
# <context mode>, <label>") - MEASURED with a probe, not guessed: an
# earlier lookup assumed "3D View Tool: Cut Plane" (no context mode) and
# the preferences keymap section never found it (user-caught). The fuzzy
# fallback in _find_tool_keymap survives future naming tweaks.
_TOOL_KEYMAP_NAME = "3D View Tool: Edit Mesh, Cut Plane"

# The tool keymap. A CONSTANT, evaluated once at import and never rebuilt -
# and that is the whole architecture, not an implementation detail.
#
# bl_keymap is template data read at register_tool() time. An earlier design
# regenerated it from preference dropdowns, which made the addon a SECOND
# WRITER on a keymap Blender already exposes for editing (it auto-injects
# this keymap into Preferences > Keymap; the toolsystem's own comment reads
# "Write into defaults, users may modify in preferences"). Two writers is
# what produced the phantom diff: changing the template underneath a user
# copy that carries a real edit makes Blender record the OLD key as a user
# modification and honor it forever, across restarts. The "fix" for that was
# restore_to_default(), which wiped every genuine edit on the keymap on each
# tool activation. With the template frozen, the phantom's precondition
# cannot occur (MEASURED: unregister_tool + register_tool + keyconfigs
# .update() against the same template leaves a user's rebind INTACT), so
# there is nothing to mitigate and nothing to destroy. The user's bindings
# live in - and are read back from - the keymap itself.
#
# The box-select drag is LEFTMOUSE unconditionally: params.tool_mouse is
# 'LEFTMOUSE' in BOTH select-mouse branches (blender_default.py:140 RCS,
# :164 LMB) and km_3d_view_tool_select_box feeds it tool_tweak_event, so
# every native tool drags on left even under right-click-select. Claiming
# the drag at all matters: unclaimed it falls through to the Tweak fallback,
# which MOVES geometry - an accidental edit gesture on a cutting tool. Plain
# clicks still select (fallback), which is what defines the Cut-Selected-Only
# domain; gizmo handles keep their drags (gizmos see the mouse first).
_TOOL_KEYMAP_BASE = (
    ("view3d.cut_plane_move_center", {"type": 'G', "value": 'PRESS'}, None),
    ("view3d.cut_plane_rotate_view", {"type": 'R', "value": 'PRESS'}, None),
    ("view3d.cut_plane_scale_plane", {"type": 'S', "value": 'PRESS'}, None),
    ("view3d.cut_plane_cut", {"type": 'RET', "value": 'PRESS'}, None),
    ("view3d.cut_plane_cut", {"type": 'NUMPAD_ENTER', "value": 'PRESS'}, None),
    # The native clear-transform vocabulary applied to the plane. Alt+G is
    # free in Edit Mesh; Alt+R shadows mesh.spin and Alt+S shadows
    # transform.shrink_fatten (blender_default.py:5626/:5500) while the tool
    # is active - kept deliberately, and rebindable in the panel.
    ("view3d.cut_plane_reset", {"type": 'G', "value": 'PRESS', "alt": True},
     {"properties": [("mode", 'LOCATION')]}),
    ("view3d.cut_plane_reset", {"type": 'R', "value": 'PRESS', "alt": True},
     {"properties": [("mode", 'ROTATION')]}),
    ("view3d.cut_plane_reset", {"type": 'S', "value": 'PRESS', "alt": True},
     {"properties": [("mode", 'SCALE')]}),
    # Tool-scoped undo: plane moves pop first, then native undo takes
    # over (operators/undo.py + pose_history). Shadows the global
    # Ctrl+Z ONLY while this tool is active - everywhere else one press
    # still undoes one cut. Redo listed first: keymap items match
    # modifiers exactly, but explicit order costs nothing.
    ("view3d.cut_plane_redo",
     {"type": 'Z', "value": 'PRESS', "ctrl": True, "shift": True}, None),
    ("view3d.cut_plane_undo",
     {"type": 'Z', "value": 'PRESS', "ctrl": True}, None),
    # Native _template_items_tool_select_actions bindings, verbatim.
    ("view3d.select_box", {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG'}, None),
    ("view3d.select_box",
     {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG', "shift": True},
     {"properties": [("mode", 'ADD')]}),
    ("view3d.select_box",
     {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG', "ctrl": True},
     {"properties": [("mode", 'SUB')]}),
    ("view3d.select_box",
     {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG', "shift": True, "ctrl": True},
     {"properties": [("mode", 'AND')]}),
)


def _oskey_twins(items) -> tuple:
    """A Cmd twin for every Ctrl item - the macOS convention, made explicit.

    Blender's manual (Platform Specific Keys): "The Cmd key can be used
    instead of Ctrl on macOS for all but a few exceptions." That
    substitution happens in the C event layer for NATIVE keymap items only -
    an addon tool keymap gets no such courtesy (measured on an M2: Cmd+Z
    did not fire the tool's Ctrl+Z undo while Ctrl+Z did). Twins are
    appended AFTER the originals so the preferences panel's first-match
    rows keep showing the Ctrl alias; the Cmd twins stay editable in
    Preferences > Keymap.
    """
    twins = []
    for idname, event, props in items:
        if event.get("ctrl"):
            twin = dict(event)
            del twin["ctrl"]
            twin["oskey"] = True
            twins.append((idname, twin, props))
    return tuple(twins)


# Still a FROZEN constant: chosen once at import per platform, never
# rebuilt at runtime - the frozen-template contract is about not mutating
# the template underneath the user's keymap copy, which this preserves.
_TOOL_KEYMAP = (_TOOL_KEYMAP_BASE + _oskey_twins(_TOOL_KEYMAP_BASE)
                if sys.platform == 'darwin' else _TOOL_KEYMAP_BASE)

CutPlaneTool.bl_keymap = _TOOL_KEYMAP

# The default transform keys, as they appear in _TOOL_KEYMAP above. Only a
# fallback for when the keymap itself cannot be read (dev_load sessions
# before registration, restricted startup contexts).
_DEFAULT_TRANSFORM_KEYS = ('G', 'R', 'S')

_TRANSFORM_IDNAMES = (
    "view3d.cut_plane_move_center",
    "view3d.cut_plane_rotate_view",
    "view3d.cut_plane_scale_plane",
)

# Modifier attributes shared by KeyMapItem and Event, in a fixed order, with
# their display names. 'hyper' is included: it exists on both KeyMapItem and
# Event in 4.5 AND 5.1 (measured), and omitting it made a Hyper+G binding
# match a bare G - the very modifier-blindness this file sets out to fix.
# Reads go through getattr with a default, so an older Blender without one of
# these degrades to "not held" rather than raising.
_MOD_LABELS = (("ctrl", "Ctrl"), ("shift", "Shift"), ("alt", "Alt"),
               ("oskey", "OS"), ("hyper", "Hyper"))
_MOD_ATTRS = tuple(name for name, _label in _MOD_LABELS)


def _find_tool_keymap(kc):
    """Our keymap inside one keyconfig, by exact name then fuzzily."""
    km = kc.keymaps.get(_TOOL_KEYMAP_NAME)
    if km is None:
        km = next((k for k in kc.keymaps
                   if "Tool:" in k.name and k.name.endswith("Cut Plane")), None)
        if km is not None:
            logger.warning(
                "[CUT PLANE] tool keymap found by fuzzy name (%r); "
                "_TOOL_KEYMAP_NAME (%r) is stale", km.name, _TOOL_KEYMAP_NAME)
    return km


def tool_keymap_editable():
    """The USER keyconfig's copy - the only one safe to WRITE to.

    Deliberately not the read path's user->addon->default chain: the addon
    copy is discarded by unregister_tool (it iterates keyconfigs.default and
    .addon; the user copy is never removed), so a writable widget pointed at
    it would take an edit that silently vanishes on the next addon reload.
    """
    return _find_tool_keymap(bpy.context.window_manager.keyconfigs.user)


def tool_keymap_live():
    """The keymap that actually fires: user, else addon, else default.

    Empty copies are skipped - the default keyconfig carries a 0-item
    placeholder for this keymap (measured), which would otherwise answer
    every lookup with nothing.
    """
    wm = bpy.context.window_manager
    for kc in (wm.keyconfigs.user, wm.keyconfigs.addon, wm.keyconfigs.default):
        km = _find_tool_keymap(kc)
        if km is not None and len(km.keymap_items):
            return km
    return None


def transform_chords() -> tuple:
    """((type, mods), ...) for move/rotate/scale, READ from the live keymap.

    An entry is None when the user unbound or disabled that transform - a
    legitimate state (drive the plane from the gizmo handles only), not an
    error to paper over with defaults.

    Read every time rather than cached: a user can rebind in Preferences >
    Keymap, which fires no callback we could invalidate a cache from, so the
    cache would BE the bug. Chords are snapshotted into plain tuples because
    keyconfigs.update() dangles live KeyMapItem references.
    """
    km = tool_keymap_live()
    if km is None:
        return tuple((k, (0,) * len(_MOD_ATTRS)) for k in _DEFAULT_TRANSFORM_KEYS)
    chords = []
    for idname in _TRANSFORM_IDNAMES:
        kmi = next((i for i in km.keymap_items
                    if i.idname == idname and i.active), None)
        chords.append((kmi.type, tuple(getattr(kmi, m, 0) for m in _MOD_ATTRS))
                      if kmi is not None else None)
    return tuple(chords)


def chord_matches(chord, event) -> bool:
    """Does this event match a (type, mods) chord, modifiers included?

    -1 is Blender's KM_ANY sentinel ("any state") and matches either way.
    Does NOT check event.value - callers test PRESS themselves.
    """
    if chord is None or event.type != chord[0]:
        return False
    return all(want == -1 or bool(want) == bool(getattr(event, attr, False))
               for want, attr in zip(chord[1], _MOD_ATTRS))


def chord_label(chord, human: bool = True) -> str:
    """A chord as text: "Shift+R" (human) or "shift+R" (legend spec).

    The single formatter for both consumers - the preferences cheat sheet
    and the status-bar legend. They MUST agree: printing a bare key type
    told a user with Rotate on Shift+R to "press R again" for trackball,
    while the status bar (built from the chord) correctly said Shift+R and
    bare R did nothing. KM_ANY (-1) modifiers are omitted: they match
    whether or not the key is held, so naming one would be misleading.
    """
    if chord is None:
        return ""
    mods = [(label if human else name)
            for (name, label), state in zip(_MOD_LABELS, chord[1]) if state == 1]
    return "+".join(mods + [chord[0]])


def _ensure_tool_unregistered(tool_cls) -> None:
    """Remove any toolbar entry matching tool_cls.bl_idname, even if the original class
    object is no longer reachable (e.g. after re-executing this script in the text editor)."""
    try:
        bpy.utils.unregister_tool(tool_cls)
        return
    except Exception:
        pass  # Fall through to manual lookup by bl_idname

    # Manual fallback pokes tool-system INTERNALS (_tools); best-effort only.
    # An internals change in a future Blender must degrade to a stale toolbar
    # entry (harmless in a fresh session), never abort register().
    try:
        from bl_ui.space_toolsystem_common import ToolSelectPanelHelper
        cls = ToolSelectPanelHelper._tool_class_from_space_type(tool_cls.bl_space_type)
        if cls is None:
            return
        tools = cls._tools.get(tool_cls.bl_context_mode)
        if tools is None:
            return
        target = tool_cls.bl_idname
        # NOTE: ToolDef is itself a namedtuple, so check `idname` attribute
        # BEFORE treating an item as a group tuple - otherwise we'd iterate
        # its fields.
        for i, item in enumerate(tools):
            if item is None:
                continue
            if getattr(item, "idname", None) == target:
                del tools[i]
                return
            if isinstance(item, (tuple, list)) and not hasattr(item, "idname"):
                survivors = [s for s in item if getattr(s, "idname", None) != target]
                if len(survivors) != len(item):
                    if survivors:
                        tools[i] = tuple(survivors) if isinstance(item, tuple) else survivors
                    else:
                        del tools[i]
                    return
    except Exception:
        logger.exception("[CUT PLANE] Manual tool-entry cleanup failed")


class CutPlaneActivateOperator(Operator):
    """Activate the Cut Plane slice tool."""
    # A named entry point so the tool is findable in F3 search and can be given
    # a shortcut via right-click > Assign Shortcut (the native pattern for a
    # toolbar tool that ships without a global key, like Bisect). Deliberately
    # a wrapper over wm.tool_set_by_id - NOT a duplicate of native behavior:
    # it contributes the poll gate (Edit Mesh + 3D View only, so the menu
    # entry greys out where activation would fail) and a user-facing error
    # report; wm.tool_set_by_id alone silently raises into the console.
    bl_idname = "view3d.cut_plane_activate"
    bl_label = "Cut Plane Slice"
    bl_description = "Activate the Cut Plane slice tool"
    # No 'UNDO': switching the active tool is not a mesh edit (like picking
    # any toolbar tool, it does not push an undo step).
    bl_options = {'REGISTER'}

    @classmethod
    def poll(cls, context):
        return (context.mode == 'EDIT_MESH'
                and context.area is not None
                and context.area.type == 'VIEW_3D')

    def execute(self, context):
        try:
            bpy.ops.wm.tool_set_by_id(name=TOOL_IDNAME)
        except RuntimeError as exc:
            self.report({'WARNING'}, f"Could not activate the Cut Plane tool: {exc}")
            return {'CANCELLED'}
        return {'FINISHED'}


def _draw_mesh_menu_entry(self, context):
    """Append the activation entry to the edit-mode Mesh menu, next to where
    native Bisect / Knife live (VIEW3D_MT_edit_mesh)."""
    self.layout.separator()
    self.layout.operator(CutPlaneActivateOperator.bl_idname, icon='MOD_BOOLEAN')


def register_menu() -> None:
    """Add the Mesh-menu entry (called from the addon register()).

    Deduped by __name__ + module path (the app-handler pattern): menu draw
    functions are fresh objects per module load, so a stale copy left by a
    partially failed reload can only be caught by name - and the module
    check keeps a foreign add-on's same-named draw function untouchable.
    """
    menu = bpy.types.VIEW3D_MT_edit_mesh
    # Ownership anchor = the addon ROOT package (same rule as the app-handler
    # dedups): stale copies may carry an older layout's module path.
    root = __package__.rsplit(".", 1)[0]
    stale = [fn for fn in getattr(menu.draw, "_draw_funcs", ())
             if getattr(fn, "__name__", None) == _draw_mesh_menu_entry.__name__
             and (getattr(fn, "__module__", "") == root
                  or getattr(fn, "__module__", "").startswith(root + "."))]
    for fn in stale:
        menu.remove(fn)
    menu.append(_draw_mesh_menu_entry)


def unregister_menu() -> None:
    bpy.types.VIEW3D_MT_edit_mesh.remove(_draw_mesh_menu_entry)
